func inlineJSON(data []byte) []byte {
	result := bytes.Buffer{}
	inString := false
	escape := false
	for i := 0; i < len(data); i++ {
		b := data[i]
		if escape {
			result.WriteByte(b)
			escape = false
			continue
		}
		if b == '\\' && inString {
			result.WriteByte(b)
			escape = true
			continue
		}
		if b == '"' {
			inString = !inString
			result.WriteByte(b)
			continue
		}
		if !inString && b == '\n' {
			continue
		}
		if !inString && b == ' ' && result.Len() > 0 && result.Bytes()[result.Len()-1] != ' ' {
			result.WriteByte(b)
		} else {
			result.WriteByte(b)
		}
	}
	return result.Bytes()
}

func extractRegexName(input string) string {
	name := input
	if idx := strings.LastIndex(name, "/"); idx >= 0 {
		name = name[idx+1:]
	}
	return name
