func countNeighbors(grid [][]bool, x, y int) int {
	count := 0
	for i := -1; i <= 1; i++ {
		for j := -1; j <= 1; j++ {
			if i == 0 && j == 0 {
				continue
			}
			nx, ny := x+i, y+j
			if nx >= 0 && nx < 10 && ny >= 0 && ny < 10 {
				if grid[nx][ny] {
					count++
				}
			}
		}
	}
	return count
}

