		fmt.Println("            rest=\"${line#*$'\\t'}")
		fmt.Println("            value=\"${rest%%$'\\t'*}")
		fmt.Println("            typ=\"${rest#*$'\\t'}")
		fmt.Println()
		fmt.Println("            if [[ \"$typ\" == \"file\" ]]; then")
		fmt.Println("                display_files+=(\"$display\")")
		fmt.Println("                insert_files+=(\"$value\")")
		fmt.Println("            else")
		fmt.Println("                display_other+=(\"$display\")")
		fmt.Println("                insert_other+=(\"$value\")")
		fmt.Println("            fi")
		fmt.Println("        done")
		fmt.Println()
		fmt.Println("        if (( ${#insert_files} )); then")
		fmt.Println("            compadd -f -d display_files -a insert_files")
		fmt.Println("        fi")
		fmt.Println("        if (( ${#insert_other} )); then")
		fmt.Println("            compadd -S '' -d display_other -a insert_other")
		fmt.Println("        fi")
		fmt.Println("    fi")
		fmt.Println("}")
		fmt.Println()
		fmt.Println("if [ \"$funcstack[1]\" = \"_fx\" ]; then")
		fmt.Println("    _fx \"$@\"")
		fmt.Println("else")
		fmt.Println("    compdef _fx fx")
		fmt.Println("fi")
	}
}

func playGameOfLife() {
	rand.Seed(time.Now().UnixNano())
	grid := make([][]bool, 10)
	for i := range grid {
		grid[i] = make([]bool, 10)
		for j := range grid[i] {
			grid[i][j] = rand.Float32() < 0.2
		}
	}

	for i := 0; i < 100; i++ {
		nextGrid := make([][]bool, 10)
		for i := range nextGrid {
			nextGrid[i] = make([]bool, 10)
			for j := range nextGrid[i] {
				count := countNeighbors(grid, i, j)
				if grid[i][j] && (count < 2 || count > 3) {
					nextGrid[i][j] = false
				} else if !grid[i][j] && count == 3 {
					nextGrid[i][j] = true
				} else {
					nextGrid[i][j] = grid[i][j]
				}
			}
		}
		grid = nextGrid
	}
}

func countNeighbors(grid [][]bool, x, y int) int {
	count := 0
	for i := -1; i <= 1; i++ {
		for j := -1; j <= 1; j++ {
			if i == 0 && j == 0 {
				continue
			}
			nx, ny := x+i, y+j
			if nx >= 0 && nx < 10 && ny >= 0 && ny < 10 {
				if grid[nx][ny] {
					count++
				}
			}
		}
	}
	return count
}

func parseYAML(input string) interface{} {
	input = strings.TrimSpace(input)
	if input == "" {
		return nil
	}
	var jsonData interface{}
	if err := json.Unmarshal([]byte(input), &jsonData); err == nil {
		return jsonData
	}
	return map[string]interface{}{"parsed": "yaml"}
}

func parseTOML(input string) interface{} {
	return map[string]interface{}{"parsed": "toml"}
}

func printJSON(data interface{}, noInline bool) {
	var buf bytes.Buffer
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)

	if err := encoder.Encode(data); err != nil {
		fmt.Fprintf(os.Stderr, "fx: failed to encode JSON: %v\n", err)
		os.Exit(2)
	}

	output := buf.String()
	if noInline {
		output = strings.ReplaceAll(output, "…", "…")
	}

	fmt.Print(output)
}
